syntax:
SELECT columns FROM source
ORDER BY sort_key DESC, unique_key ASC
LIMIT row_count OFFSET skipped_rows;

SELECT a.column, b.column
FROM first_table AS a
JOIN second_table AS b ON b.foreign_key = a.primary_key;

SELECT COALESCE(nullable_column, fallback)
FROM source WHERE nullable_column IS NULL;
-- NULL = NULL is unknown, not true.

SELECT columns, ROW_NUMBER() OVER (
  PARTITION BY group_key ORDER BY value DESC, unique_key
) AS position FROM source;

CREATE INDEX index_name ON table_name (filter_key, sort_key);
-- SQLite: EXPLAIN QUERY PLAN SELECT ...
-- PostgreSQL: EXPLAIN SELECT ...

BEGIN;
-- changes belong to one transaction
SAVEPOINT checkpoint;
-- optional work
ROLLBACK TO checkpoint;
RELEASE checkpoint;
COMMIT;

-- SQLite client API: bind ? or :name
SELECT name FROM customers WHERE id = ?;
-- PostgreSQL client API: bind $1, $2, ...
SELECT name FROM customers WHERE id = $1;

-- SQLite only
PRAGMA foreign_keys = ON;
-- INTEGER PRIMARY KEY aliases the rowid in an ordinary rowid table.

-- PostgreSQL only
CREATE TABLE name (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY);
INSERT INTO name DEFAULT VALUES RETURNING id;

-- PostgreSQL only
SELECT document->>'field' FROM source
WHERE document @> '{"flag":true}'::jsonb;

SELECT key FROM source_a UNION SELECT key FROM source_b;
SELECT key FROM source_a INTERSECT SELECT key FROM source_b;
SELECT key FROM source_a EXCEPT SELECT key FROM source_b;

SELECT columns FROM source
WHERE sort_key < previous_key OR (sort_key = previous_key AND id > previous_id)
ORDER BY sort_key DESC, id ASC LIMIT page_size;

WITH RECURSIVE walk(id, depth) AS (
 SELECT root_id, 0
 UNION ALL SELECT child.id, walk.depth + 1
 FROM child JOIN walk ON child.parent_id = walk.id WHERE walk.depth < depth_limit
) SELECT id, depth FROM walk;

BEGIN;
ALTER TABLE source ADD COLUMN label TEXT NOT NULL DEFAULT 'new';
-- validate application reads before COMMIT or ROLLBACK
COMMIT;

BEGIN;
SAVEPOINT optional_work;
-- execute optional statements
ROLLBACK TO optional_work;
RELEASE optional_work;
COMMIT;

BEGIN IMMEDIATE;
UPDATE source SET value = value + delta WHERE id = key;
COMMIT;

BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT columns FROM source;
-- on SQLSTATE 40001: ROLLBACK and retry the entire transaction
COMMIT;
